{
  "verdict": "correction_required",
  "humanApproval": false,
  "findings": [
    {
      "severity": "high",
      "evidencePath": "packages/workflow-control/src/gitDeliveryPort.ts",
      "location": "LocalGitDeliveryPort.#createExactCommitLocked and mutate; storage.ts: WorkflowStore.guardGovernedMutation",
      "reason": "Ordinary Git delivery checks lease expiry only before entering the adapter. The adapter then performs multiple blocking Git commands before commit-tree/update-ref; create-ref and push also perform blocking observations before their writes. The SQLite writer reservation prevents takeover but does not prevent time-based lease expiry. Unlike bootstrap, ordinary delivery has no fresh fence check immediately before these effects, so an expired owner can still write. The new tests replace leases before adapter entry and do not cover expiry during adapter observations.",
      "proposedCorrection": "Carry a mandatory dispatch guard into the ordinary Git adapter and recheck current lease time immediately before each actual write or remote dispatch while retaining the writer reservation. Add regressions that expire leases during Git observations and assert no subsequent commit/ref/push effect."
    },
    {
      "severity": "high",
      "evidencePath": "packages/workflow-control/src/reconciliation.ts",
      "location": "JournaledMutationBroker.execute and reconcilePrepared, immediately before #port.mutate; storage.ts: WorkflowStore.assertTransitionLeases",
      "reason": "The supplied Beads/Dolt transition path still bypasses document verification at effect dispatch. After prepareTransition verifies documents, execute awaits port.observe and then checks only leases before invoking mutate. Recovery similarly adopts a prepared transition, awaits observation and checks only leases. A document change or approval invalidation during that observation therefore permits claimIssue, closeIssue or pushDolt before commitTransition rejects settlement. This is a concrete uncovered authority boundary under DB-4, independent of the repaired ordinary delivery broker.",
      "proposedCorrection": "Add durable document verification and approval/cancellation/lease checks at transition effect initiation, serialized by a writer reservation. Apply it to execution and recovery. Test changes and invalidation during suspended Beads/Dolt observations with zero subsequent mutation calls."
    }
  ],
  "resolvedPriorFindings": [
    {
      "finding": "Ordinary delivery mutations escape guarded dispatch",
      "assessment": "Partially resolved. Execute, replay and merge now enter guardGovernedMutation, closing the pre-adapter invalidation/takeover gap. Lease expiry during blocking adapter work remains."
    },
    {
      "finding": "Verification and commit use different workspaces",
      "assessment": "Resolved in the supplied ordinary Git path. Per-call ports use the verified source, enforce the same common directory and check normative blobs in created/adopted trees and push/create-ref targets."
    },
    {
      "finding": "Credential issuance and container start ignore durable cancellation",
      "assessment": "Resolved at the supplied dispatch boundaries. Credential issue and container create/start check durable cancellation under writer reservation. Launcher progression also checks cancellation, while cleanup remains available."
    }
  ],
  "bootstrapAssessment": "The supplied bootstrap callbacks remain synchronous through local Git writes and remote adapter subprocess initiation. withinDeliveryMutation reuses the active store reservation; journal approval/fence checks do not open a competing writer transaction. No additional asynchronous escape is evident in this supplied bootstrap chain.",
  "coverageLimits": [
    "Static review of supplied evidence only; no commands executed or state changed, and hashes were not independently recomputed.",
    "Current test reruns are pending. Supplied tests establish intended assertions, not passing results at this snapshot.",
    "Production ordinary remote Git, GitHub and Beads client implementations are absent. Their actual mutation initiation before any internal asynchronous suspension remains unproved.",
    "The added regressions do not cover ordinary Git lease expiry during blocking adapter observations or Beads/Dolt document invalidation during suspended observations.",
    "This bounded follow-up does not establish complete DB-T01–11 coverage, hosted-check success or human approval."
  ]
}
